        private static void OpenProjection(Window owner, DeepSystemsContext ctx, WorldIndex index, string sourceKind, string sourceId, string fingerprint, Func<SpatialWorldModel> create)
        {
            Load(ctx); SpatialWorldModel existing = Store.Models.Where(x => Eq(x.SourceKind, sourceKind) && Eq(x.SourceId, sourceId)).OrderByDescending(x => x.Revision).FirstOrDefault();
            if (existing != null && Eq(existing.SourceFingerprint, fingerprint)) { OpenModel(owner, ctx, index, existing); return; }
            if (existing != null) { MessageBoxResult drift = MessageBox.Show(owner, "The upstream source fingerprint changed.\n\nYES — fork a new spatial child from current source\nNO — open the historical projection unchanged\nCANCEL — return", "YOMI · SOURCE DRIFT", MessageBoxButton.YesNoCancel, MessageBoxImage.Warning); if (drift == MessageBoxResult.No) { OpenModel(owner, ctx, index, existing); return; } if (drift != MessageBoxResult.Yes) return; }
            SpatialWorldModel model = create(); model.Id = Id("spatial-world"); model.ParentModelId = existing == null ? null : existing.Id; model.SourceKind = sourceKind; model.SourceId = sourceId; model.SourceFingerprint = fingerprint; model.CreatedUtc = model.UpdatedUtc = Now(); Store.Models.Insert(0, model); Save(ctx); AppendLedger(ctx, existing == null ? "PROJECTION_CREATED" : "SOURCE_DRIFT_FORKED", model.Id, sourceKind + ":" + sourceId, SpatialKernel.Fingerprint(model), fingerprint); OpenModel(owner, ctx, index, model);
        }

