            Portal(chambers, "DISTΩ", "DISTRIBUTED SYSTEMS PLANETARIUM", "Project regions, sites and infrastructure into explicit fault domains, nodes and network paths without promoting geographic labels into production topology.", delegate { SpatialWorldModel m = ChooseModel(w); if (m != null) DistributedSystemsPlanetarium.OpenFromSpatialWorld(w, ctx, index, m); });
            Portal(chambers, "SECΩ", "ADVERSARIAL SECURITY FORTRESS", "Project places, territories and infrastructure into zones, facilities, defended corridors and recovery boundaries without production authority.", delegate { SpatialWorldModel m = ChooseModel(w); if (m != null) AdversarialSecurityFortress.OpenFromSpatialWorld(w, ctx, index, m); });
            Portal(chambers, "DATAΩ", "DATA FOUNDRY", "Project places, territories, routes and infrastructure metadata into structured provenance and relation analysis.", delegate { SpatialWorldModel m = ChooseModel(w); if (m != null) DataFoundry.OpenFromSpatialWorld(w, ctx, index, m); });
            Portal(chambers, "GENOMEΩ", "SOFTWARE GENOME", "Project topology/domain context into software architecture investigation.", delegate { SpatialWorldModel m = ChooseModel(w); if (m != null) SoftwareGenomeObservatory.OpenFromSpatialWorld(w, ctx, index, m); });
            Portal(chambers, "DOCΩ", "LIVING DOCUMENT", "Project places, routes, hazards and accessibility evidence into a traceable spatial dossier.", delegate { SpatialWorldModel m = ChooseModel(w); if (m != null) LivingDocumentIntelligenceFactory.OpenFromSpatialWorld(w, ctx, index, m); });
            Portal(chambers, "EXPΩ", "EXPEDITION COMMAND", "Capture the active spatial world as a fingerprinted mission crossing with places, routes, hazards and accessibility evidence retained.", delegate { SpatialWorldModel m = ChooseModel(w); if (m != null) GrandUnifiedExpeditionCommand.OpenFromSpatialWorld(w, ctx, index, m); });
            scroll.Content = chambers; root.Children.Add(scroll); w.Content = root; w.Show();
        }

        private static void OpenModels(Window owner, DeepSystemsContext ctx, WorldIndex index) { object choice = ChooseObject(owner, "SPATIAL WORLDS", "Select a retained world.", Store.Models.Cast<object>().ToList()); SpatialWorldModel model = choice as SpatialWorldModel; if (model != null) OpenModel(owner, ctx, index, model); }
        private static void OpenModel(Window owner, DeepSystemsContext ctx, WorldIndex index, SpatialWorldModel model)
        {
            Window w = W(owner, "YOMI · " + (model.Name ?? "SPATIAL WORLD"), 1380, 900); DockPanel root = Shell(model.Name ?? "SPATIAL WORLD", model.Description + "\n" + model + "   ·   fingerprint " + Short(SpatialKernel.Fingerprint(model), 24) + (String.IsNullOrWhiteSpace(model.SourceKind) ? "" : "   ·   source " + model.SourceKind + ":" + model.SourceId));
            WrapPanel actions = new WrapPanel(); actions.Children.Add(Btn("PLACES", delegate { OpenCollection(w, "PLACES", model.Places.Cast<object>().ToList(), "Stable nested place identity."); })); actions.Children.Add(Btn("TERRITORIES", delegate { OpenCollection(w, "TERRITORIES", model.Territories.Cast<object>().ToList(), "Polygonal jurisdictions and regions."); })); actions.Children.Add(Btn("CONNECTIONS", delegate { OpenCollection(w, "CONNECTIONS", model.Connections.Cast<object>().ToList(), "Multimodal graph edges."); })); actions.Children.Add(Btn("INFRASTRUCTURE", delegate { OpenCollection(w, "INFRASTRUCTURE", model.Infrastructure.Cast<object>().ToList(), "Facilities and dependency chains."); })); actions.Children.Add(Btn("INFRA CASCADE", delegate { ComputeInfrastructure(w, model); })); actions.Children.Add(Btn("MOVERS", delegate { OpenCollection(w, "MOVERS", model.Entities.Cast<object>().ToList(), "Mobile entities and itineraries."); })); actions.Children.Add(Btn("SCENARIOS", delegate { OpenCollection(w, "SCENARIOS", model.Scenarios.Cast<object>().ToList(), "Counterfactual spatial worlds."); })); actions.Children.Add(Btn("TOPOLOGY", delegate { ComputeTopology(w, ctx, model); })); actions.Children.Add(Btn("ROUTE", delegate { ComputeRoute(w, ctx, model); })); actions.Children.Add(Btn("ACCESSIBILITY", delegate { ComputeIsochrone(w, model); })); actions.Children.Add(Btn("MOVEMENT", delegate { ComputeMovement(w, ctx, model); })); actions.Children.Add(Btn("STRESS", delegate { ComputeStress(w, ctx, model); })); actions.Children.Add(Btn("INDEX", delegate { ComputeIndex(w, ctx, model); })); actions.Children.Add(Btn("ADD…", delegate { EditWorld(w, ctx, index, model); })); actions.Children.Add(Btn("FORK", delegate { ForkWorldFrom(w, ctx, index, model); })); actions.Children.Add(Btn("BASELINE", delegate { FreezeBaselineFor(w, ctx, model); })); actions.Children.Add(Btn("DOSSIER", delegate { CreateDossierFor(w, ctx, model); })); DockPanel.SetDock(actions, Dock.Top); root.Children.Add(actions);
            List<object> rows = new List<object>(); rows.Add("CRS   ·   " + model.CoordinateSystems.Count + "   LAYERS   ·   " + model.Layers.Count); rows.Add("PLACES   ·   " + model.Places.Count + "   TERRITORIES   ·   " + model.Territories.Count + "   CONNECTIONS   ·   " + model.Connections.Count); rows.Add("INFRASTRUCTURE   ·   " + model.Infrastructure.Count + "   ENTITIES   ·   " + model.Entities.Count + "   EVENTS   ·   " + model.Events.Count + "   SCENARIOS   ·   " + model.Scenarios.Count); rows.Add("ASSUMPTIONS   ·   " + model.Assumptions.Count + "   EVIDENCE NODES   ·   " + model.EvidenceNodeIds.Count); rows.AddRange(SpatialKernel.Validate(model).Cast<object>()); ListBox list = List(); list.ItemsSource = rows; root.Children.Add(list); w.Content = root; w.Show();
        }

        private static void ChooseAndRoute(Window owner, DeepSystemsContext ctx, WorldIndex index) { SpatialWorldModel m = ChooseModel(owner); if (m != null) ComputeRoute(owner, ctx, m); }
        private static void ComputeRoute(Window owner, DeepSystemsContext ctx, SpatialWorldModel m) { SpatialPlace from = ChooseObject(owner, "ROUTE ORIGIN", "Choose origin.", m.Places.Cast<object>().ToList()) as SpatialPlace; if (from == null) return; SpatialPlace to = ChooseObject(owner, "ROUTE DESTINATION", "Choose destination.", m.Places.Where(x => !Eq(x.Id, from.Id)).Cast<object>().ToList()) as SpatialPlace; if (to == null) return; SpatialScenario scenario = ChooseOptionalScenario(owner, m); string mode = Prompt(owner, "MODE FILTER", "ANY, WALK, ROAD, RAIL, AIR, MARITIME, CORRIDOR, ELEVATOR or PORTAL", "ANY"); if (mode == null) return; SpatialRouteResult route = SpatialKernel.Route(m, from.Id, to.Id, scenario, mode, "PUBLIC"); SpatialRouteArtifact artifact = new SpatialRouteArtifact { Id = Id("spatial-route"), ModelId = m.Id, CreatedUtc = Now(), ModelFingerprint = SpatialKernel.Fingerprint(m), CertificateHash = route.RouteHash, Result = route }; Store.Routes.Insert(0, artifact); Save(ctx); AppendLedger(ctx, "ROUTE_COMPUTED", m.Id, route.ToString(), artifact.ModelFingerprint, artifact.CertificateHash); List<object> rows = new List<object> { route }; rows.AddRange(route.Legs.Cast<object>()); rows.AddRange(route.Diagnostics.Cast<object>()); OpenCollection(owner, "ROUTE ORACLE", rows, "Immutable route artifact " + artifact.Id); }
        private static void ChooseAndIsochrone(Window owner) { SpatialWorldModel m = ChooseModel(owner); if (m != null) ComputeIsochrone(owner, m); }
        private static void ComputeIsochrone(Window owner, SpatialWorldModel m) { SpatialPlace from = ChooseObject(owner, "ISOCHRONE ORIGIN", "Choose origin.", m.Places.Cast<object>().ToList()) as SpatialPlace; if (from == null) return; double seconds = Number(Prompt(owner, "TIME BUDGET", "Maximum travel seconds", "1800"), 1800); List<SpatialReachabilityRecord> rows = SpatialKernel.Isochrone(m, from.Id, null, "ANY", "PUBLIC", seconds); OpenCollection(owner, "ACCESSIBILITY ISOCHRONE", rows.Cast<object>().ToList(), rows.Count + " places reachable from " + from.Id + " inside " + seconds.ToString("0.##", CultureInfo.InvariantCulture) + " seconds."); }
        private static void ChooseAndTopology(Window owner, DeepSystemsContext ctx) { SpatialWorldModel m = ChooseModel(owner); if (m != null) ComputeTopology(owner, ctx, m); }
        private static void ComputeTopology(Window owner, DeepSystemsContext ctx, SpatialWorldModel m) { SpatialTopologyResult result = SpatialKernel.AnalyzeTopology(m); SpatialTopologyArtifact artifact = new SpatialTopologyArtifact { Id = Id("spatial-topology"), ModelId = m.Id, CreatedUtc = Now(), ModelFingerprint = SpatialKernel.Fingerprint(m), CertificateHash = result.CertificateHash, Result = result }; Store.Topologies.Insert(0, artifact); Save(ctx); AppendLedger(ctx, "TOPOLOGY_ANALYZED", m.Id, result.ToString(), artifact.ModelFingerprint, artifact.CertificateHash); List<object> rows = new List<object> { result, "ARTICULATION PLACES   ·   " + String.Join(", ", result.ArticulationPlaceIds.ToArray()), "BRIDGE CONNECTIONS   ·   " + String.Join(", ", result.BridgeConnectionIds.ToArray()) }; rows.AddRange(result.Issues.Cast<object>()); OpenCollection(owner, "TOPOLOGY REACTOR", rows, "Graph, hierarchy, geometry and referential-integrity certificate " + result.CertificateHash); }
        private static void ChooseAndMovement(Window owner, DeepSystemsContext ctx) { SpatialWorldModel m = ChooseModel(owner); if (m != null) ComputeMovement(owner, ctx, m); }
        private static void ComputeMovement(Window owner, DeepSystemsContext ctx, SpatialWorldModel m) { SpatialScenario scenario = ChooseOptionalScenario(owner, m); int ticks = Integer(Prompt(owner, "MOVEMENT HORIZON", "Ticks (1–4096)", "512"), 512, 1, 4096); SpatialMovementResult result = SpatialKernel.SimulateMovement(m, scenario, ticks, 60); SpatialMovementArtifact artifact = new SpatialMovementArtifact { Id = Id("spatial-movement"), ModelId = m.Id, CreatedUtc = Now(), ModelFingerprint = SpatialKernel.Fingerprint(m), CertificateHash = result.CertificateHash, Result = result }; Store.Movements.Insert(0, artifact); Save(ctx); AppendLedger(ctx, "MOVEMENT_SIMULATED", m.Id, result.ToString(), artifact.ModelFingerprint, artifact.CertificateHash); List<object> rows = new List<object> { result }; rows.AddRange(result.Movements.Take(8192).Cast<object>()); OpenCollection(owner, "MOVEMENT THEATER", rows, "Deterministic BPR congestion loading; results do not dispatch real entities."); }
        private static void ChooseAndStress(Window owner, DeepSystemsContext ctx) { SpatialWorldModel m = ChooseModel(owner); if (m != null) ComputeStress(owner, ctx, m); }
        private static void ComputeStress(Window owner, DeepSystemsContext ctx, SpatialWorldModel m) { List<SpatialStressWorldResult> worlds = SpatialKernel.StressWorlds(m); string certificate = HashText(SpatialKernel.Fingerprint(m) + "|" + String.Join("|", worlds.Select(x => x.CertificateHash).ToArray())); SpatialStressArtifact artifact = new SpatialStressArtifact { Id = Id("spatial-stress"), ModelId = m.Id, CreatedUtc = Now(), ModelFingerprint = SpatialKernel.Fingerprint(m), CertificateHash = certificate, Worlds = worlds }; Store.StressRuns.Insert(0, artifact); Save(ctx); AppendLedger(ctx, "STRESS_WORLDS_COMPUTED", m.Id, worlds.Count + " worlds", artifact.ModelFingerprint, artifact.CertificateHash); List<object> rows = new List<object>(); foreach (SpatialStressWorldResult world in worlds) { rows.Add(world); rows.Add("FAILED INFRASTRUCTURE   ·   " + (world.FailedInfrastructureIds.Count == 0 ? "∅" : String.Join(", ", world.FailedInfrastructureIds.ToArray()))); rows.AddRange(world.CriticalAssets.Cast<object>()); } OpenCollection(owner, "RESILIENCE CARTOGRAPHY", rows, "Scenario-isolated accessibility, infrastructure-cascade, travel-tail and critical-corridor results."); }
        private static void ChooseAndInfrastructure(Window owner) { SpatialWorldModel m = ChooseModel(owner); if (m != null) ComputeInfrastructure(owner, m); }
        private static void ComputeInfrastructure(Window owner, SpatialWorldModel m) { SpatialScenario scenario = ChooseOptionalScenario(owner, m); SpatialInfrastructureCascadeResult cascade = SpatialKernel.InfrastructureCascade(m, scenario); List<object> rows = new List<object> { cascade }; rows.AddRange(m.Infrastructure.Cast<object>()); rows.AddRange(cascade.Audit.Cast<object>()); OpenCollection(owner, "INFRASTRUCTURE CONSTELLATION", rows, "Condition/redundancy direct failure and bounded dependency fixed point · certificate " + cascade.CertificateHash); }
        private static void ChooseAndCriticality(Window owner) { SpatialWorldModel m = ChooseModel(owner); if (m == null) return; SpatialScenario scenario = ChooseOptionalScenario(owner, m); OpenCollection(owner, "CRITICAL CORRIDORS", SpatialKernel.Criticality(m, scenario, 128).Cast<object>().ToList(), "Marginal accessibility loss after individually removing active connections."); }
        private static void ChooseAndIndex(Window owner, DeepSystemsContext ctx) { SpatialWorldModel m = ChooseModel(owner); if (m != null) ComputeIndex(owner, ctx, m); }
        private static void ComputeIndex(Window owner, DeepSystemsContext ctx, SpatialWorldModel m) { double size = Number(Prompt(owner, "INDEX CELL SIZE", "Coordinate-unit cell size", "1000"), 1000); SpatialIndexResult result = SpatialKernel.BuildIndex(m, size); SpatialIndexArtifact artifact = new SpatialIndexArtifact { Id = Id("spatial-index"), ModelId = m.Id, CreatedUtc = Now(), ModelFingerprint = SpatialKernel.Fingerprint(m), CertificateHash = result.CertificateHash, Result = result }; Store.Indexes.Insert(0, artifact); Save(ctx); AppendLedger(ctx, "SPATIAL_INDEX_BUILT", m.Id, result.ToString(), artifact.ModelFingerprint, artifact.CertificateHash); OpenCollection(owner, "SPATIAL INDEX", result.Cells.Cast<object>().ToList(), result.ToString() + "   ·   " + result.CertificateHash); }
        private static void OpenGeometry(Window owner) { SpatialWorldModel m = ChooseModel(owner); if (m == null) return; List<object> rows = new List<object>(); foreach (SpatialTerritory t in m.Territories) rows.Add((t.Name ?? t.Id) + "   ·   coordinate-area " + SpatialKernel.PolygonArea(t).ToString("0.######", CultureInfo.InvariantCulture) + "   ·   contains " + m.Places.Count(p => p.Position != null && SpatialKernel.Contains(t, p.Position)) + " places"); SpatialCoordinateReference crs = m.CoordinateSystems.FirstOrDefault(x => Eq(x.Id, m.DefaultCrsId)); for (int i = 0; i + 1 < m.Places.Count && i < 128; i++) rows.Add(m.Places[i].Id + " ⇄ " + m.Places[i + 1].Id + "   ·   " + SpatialKernel.DistanceMeters(m.Places[i].Position, m.Places[i + 1].Position, crs).ToString("0.###", CultureInfo.InvariantCulture) + "m"); OpenCollection(owner, "GEOMETRY CHAMBER", rows, "Coordinate-dependent results carry the model CRS; field/survey authority is not implied."); }

        private static void ChooseAndEdit(Window owner, DeepSystemsContext ctx, WorldIndex index) { SpatialWorldModel m = ChooseModel(owner); if (m != null) EditWorld(owner, ctx, index, m); }
        private static void EditWorld(Window owner, DeepSystemsContext ctx, WorldIndex index, SpatialWorldModel m)
        {
            string action = Prompt(owner, "WORLD CONSTRUCTION", "Enter PLACE, CONNECTION, TERRITORY, INFRASTRUCTURE, ENTITY, EVENT, SCENARIO or ASSUMPTION", "PLACE"); if (action == null) return;
            if (Eq(action, "PLACE")) { string raw = PromptLarge(owner, "ADD PLACE", "id|name|kind|parent|x|y|z|capacity|population", "new-place|New Place|SITE||0|0|0|100|0"); string[] p = Fields(raw); if (p.Length >= 9 && m.Places.Count < SpatialKernel.MaxPlaces) m.Places.Add(new SpatialPlace { Id = Key(p[0]), Name = p[1], Kind = p[2], ParentId = p[3], LayerId = "places", CrsId = m.DefaultCrsId, Position = new SpatialCoordinate(Number(p[4], 0), Number(p[5], 0), Number(p[6], 0)), Capacity = Number(p[7], 0), Population = Number(p[8], 0) }); else return; }
            else if (Eq(action, "CONNECTION")) { string raw = PromptLarge(owner, "ADD CONNECTION", "id|from|to|mode|bidirectional|length_m|seconds|capacity_hour|cost|risk", "new-link|hub|new-place|ROAD|true|1000|90|600|0|0.01"); string[] p = Fields(raw); if (p.Length >= 10 && m.Connections.Count < SpatialKernel.MaxConnections) m.Connections.Add(new SpatialConnection { Id = Key(p[0]), FromPlaceId = p[1], ToPlaceId = p[2], Mode = p[3], Bidirectional = Bool(p[4], true), LengthMeters = Number(p[5], 0), FreeFlowSeconds = Number(p[6], 0), CapacityPerHour = Number(p[7], 0), MonetaryCost = Number(p[8], 0), Risk = Number(p[9], 0) }); else return; }
            else if (Eq(action, "TERRITORY")) { string raw = PromptLarge(owner, "ADD TERRITORY", "id|name|kind|parent|jurisdiction|x1,y1;x2,y2;x3,y3...", "new-territory|New Territory|DISTRICT||MODEL|0,0;1000,0;1000,1000;0,1000"); string[] p = (raw ?? "").Split(new[] { '|' }, 6); if (p.Length >= 6 && m.Territories.Count < SpatialKernel.MaxTerritories) { SpatialRing ring = new SpatialRing { Id = Key(p[0]) + "-shell" }; foreach (string pair in p[5].Split(';')) { string[] xy = pair.Split(','); if (xy.Length >= 2) ring.Vertices.Add(new SpatialCoordinate(Number(xy[0], 0), Number(xy[1], 0), 0)); } m.Territories.Add(new SpatialTerritory { Id = Key(p[0]), Name = p[1], Kind = p[2], ParentId = p[3], Jurisdiction = p[4], LayerId = "territories", CrsId = m.DefaultCrsId, Rings = new List<SpatialRing> { ring } }); } else return; }
            else if (Eq(action, "INFRASTRUCTURE")) { string raw = PromptLarge(owner, "ADD INFRASTRUCTURE", "id|name|kind|place|territory|capacity|condition|criticality|dependencies_csv", "new-infra|New Infrastructure|FACILITY|hub|core-region|1000|1|0.5|"); string[] p = Fields(raw); if (p.Length >= 9 && m.Infrastructure.Count < SpatialKernel.MaxInfrastructure) m.Infrastructure.Add(new SpatialInfrastructure { Id = Key(p[0]), Name = p[1], Kind = p[2], PlaceId = p[3], TerritoryId = p[4], Capacity = Number(p[5], 0), Condition = Number(p[6], 1), Criticality = Number(p[7], 0), DependencyIds = Tokens(p[8]) }); else return; }
            else if (Eq(action, "ENTITY")) { string raw = PromptLarge(owner, "ADD MOBILE ENTITY", "id|name|kind|origin|destination|mode|speed_mps|size|priority|access", "new-entity|New Entity|VEHICLE|hub|port|ROAD|12|1|1|PUBLIC"); string[] p = Fields(raw); if (p.Length >= 10 && m.Entities.Count < SpatialKernel.MaxEntities) m.Entities.Add(new SpatialEntity { Id = Key(p[0]), Name = p[1], Kind = p[2], CurrentPlaceId = p[3], DestinationPlaceId = p[4], PreferredMode = p[5], SpeedMetersPerSecond = Number(p[6], 1), Size = Number(p[7], 1), Priority = Number(p[8], 1), AccessClass = p[9] }); else return; }
            else if (Eq(action, "EVENT")) { string raw = PromptLarge(owner, "ADD EVENT", "id|name|kind|place|territory|start_s|end_s|magnitude|radius_m", "new-event|New Event|CLOSURE|hub||0|3600|0.5|1000"); string[] p = Fields(raw); if (p.Length >= 9 && m.Events.Count < SpatialKernel.MaxEvents) m.Events.Add(new SpatialEvent { Id = Key(p[0]), Name = p[1], Kind = p[2], PlaceId = p[3], TerritoryId = p[4], StartSecond = Number(p[5], 0), EndSecond = Number(p[6], 0), Magnitude = Number(p[7], 0), RadiusMeters = Number(p[8], 0) }); else return; }
            else if (Eq(action, "SCENARIO")) { string raw = PromptLarge(owner, "ADD SCENARIO", "id|name|weight|demand|speed|capacity|reliability|hazard|closed_links_csv", "new-world|New World|1|1|1|1|1|0|"); string[] p = Fields(raw); if (p.Length >= 9 && m.Scenarios.Count < SpatialKernel.MaxScenarios) m.Scenarios.Add(new SpatialScenario { Id = Key(p[0]), Name = p[1], Weight = Number(p[2], 1), DemandMultiplier = Number(p[3], 1), SpeedMultiplier = Number(p[4], 1), CapacityMultiplier = Number(p[5], 1), ReliabilityMultiplier = Number(p[6], 1), HazardMagnitude = Number(p[7], 0), ClosedConnectionIds = p[8] }); else return; }
            else if (Eq(action, "ASSUMPTION")) { string raw = PromptLarge(owner, "ADD ASSUMPTION", "Explicit model assumption", ""); if (String.IsNullOrWhiteSpace(raw)) return; m.Assumptions.Add(Short(raw, MaxLongText)); } else return;
            Touch(m); Save(ctx); string fp = SpatialKernel.Fingerprint(m); AppendLedger(ctx, "WORLD_MUTATED", m.Id, action.ToUpperInvariant(), fp, ""); OpenModel(owner, ctx, index, m);
        }

        private static void ForkWorld(Window owner, DeepSystemsContext ctx, WorldIndex index) { SpatialWorldModel m = ChooseModel(owner); if (m != null) ForkWorldFrom(owner, ctx, index, m); }
        private static void ForkWorldFrom(Window owner, DeepSystemsContext ctx, WorldIndex index, SpatialWorldModel parent) { string name = Prompt(owner, "FORK WORLD", "Name for the counterfactual child", (parent.Name ?? "Spatial world") + " · branch"); if (name == null) return; SpatialWorldModel child = Json.Deserialize<SpatialWorldModel>(Json.Serialize(parent)); child.Id = Id("spatial-world"); child.ParentModelId = parent.Id; child.Name = Short(name, MaxShortText); child.Revision = 1; child.CreatedUtc = child.UpdatedUtc = Now(); Store.Models.Insert(0, child); Save(ctx); AppendLedger(ctx, "WORLD_FORKED", child.Id, "parent=" + parent.Id, SpatialKernel.Fingerprint(child), ""); OpenModel(owner, ctx, index, child); }
        private static void CreateCapsule(Window owner, DeepSystemsContext ctx) { SpatialWorldModel m = ChooseModel(owner); if (m == null) return; string title = Prompt(owner, "PREREGISTER EXPEDITION", "Frozen expedition title", "Accessibility expedition · " + (m.Name ?? m.Id)); if (title == null) return; SpatialExpeditionCapsule c = new SpatialExpeditionCapsule { Id = Id("spatial-capsule"), ModelId = m.Id, Title = Short(title, MaxShortText), Question = "Which modeled places remain mutually accessible under the declared scenario and constraints?", Hypothesis = "The declared network retains bounded accessibility without concentrating isolation in one territory.", ScenarioId = m.Scenarios.FirstOrDefault() == null ? "BASE" : m.Scenarios.First().Id, OriginPlaceId = m.Places.FirstOrDefault() == null ? null : m.Places.First().Id, DestinationPlaceId = m.Places.Skip(1).FirstOrDefault() == null ? null : m.Places.Skip(1).First().Id, FrozenUtc = Now(), ModelFingerprint = SpatialKernel.Fingerprint(m), FrozenParameters = new Dictionary<string, double>(m.Parameters, StringComparer.OrdinalIgnoreCase), Assumptions = m.Assumptions.Take(2048).ToList(), EvidenceNodeIds = m.EvidenceNodeIds.Take(MaxEvidence).ToList() }; c.CertificateHash = HashText(Json.Serialize(c)); Store.Capsules.Insert(0, c); Save(ctx); AppendLedger(ctx, "EXPEDITION_PREREGISTERED", c.Id, c.Title, c.ModelFingerprint, c.CertificateHash); OpenCollection(owner, "EXPEDITION CAPSULE", new List<object> { c, c.AuthorityBoundary, c.AcceptanceRule }, "Frozen before computation; edits require a new capsule."); }
        private static void FreezeBaseline(Window owner, DeepSystemsContext ctx) { SpatialWorldModel m = ChooseModel(owner); if (m != null) FreezeBaselineFor(owner, ctx, m); }
        private static void FreezeBaselineFor(Window owner, DeepSystemsContext ctx, SpatialWorldModel m) { string reason = PromptLarge(owner, "FREEZE BASELINE", "Reason for immutable configuration snapshot", "Spatial configuration checkpoint before scenario descent."); if (reason == null) return; string snapshot = Json.Serialize(m); SpatialWorldBaseline prior = Store.Baselines.FirstOrDefault(x => Eq(x.ModelId, m.Id)); SpatialWorldBaseline b = new SpatialWorldBaseline { Id = Id("spatial-baseline"), ModelId = m.Id, ParentBaselineId = prior == null ? null : prior.Id, Name = (m.Name ?? m.Id) + " · baseline", Reason = Short(reason, MaxLongText), Status = "FROZEN", FrozenUtc = Now(), ModelFingerprint = SpatialKernel.Fingerprint(m), SnapshotJson = snapshot, BaselineFingerprint = HashText(snapshot) }; Store.Baselines.Insert(0, b); Save(ctx); AppendLedger(ctx, "BASELINE_FROZEN", b.Id, b.Reason, b.ModelFingerprint, b.BaselineFingerprint); OpenCollection(owner, "SPATIAL BASELINE", new List<object> { b }, "Immutable serialized world snapshot."); }
        private static void CreateDossier(Window owner, DeepSystemsContext ctx) { SpatialWorldModel m = ChooseModel(owner); if (m != null) CreateDossierFor(owner, ctx, m); }
        private static void CreateDossierFor(Window owner, DeepSystemsContext ctx, SpatialWorldModel m) { string title = Prompt(owner, "SPATIAL DOSSIER", "Dossier title", "Spatial decision dossier · " + (m.Name ?? m.Id)); if (title == null) return; SpatialDecisionDossier d = new SpatialDecisionDossier { Id = Id("spatial-dossier"), ModelId = m.Id, Title = Short(title, MaxShortText), CreatedUtc = Now(), UpdatedUtc = Now(), ModelFingerprint = SpatialKernel.Fingerprint(m), RouteId = Store.Routes.FirstOrDefault(x => Eq(x.ModelId, m.Id)) == null ? null : Store.Routes.First(x => Eq(x.ModelId, m.Id)).Id, TopologyId = Store.Topologies.FirstOrDefault(x => Eq(x.ModelId, m.Id)) == null ? null : Store.Topologies.First(x => Eq(x.ModelId, m.Id)).Id, MovementId = Store.Movements.FirstOrDefault(x => Eq(x.ModelId, m.Id)) == null ? null : Store.Movements.First(x => Eq(x.ModelId, m.Id)).Id, StressId = Store.StressRuns.FirstOrDefault(x => Eq(x.ModelId, m.Id)) == null ? null : Store.StressRuns.First(x => Eq(x.ModelId, m.Id)).Id, IndexId = Store.Indexes.FirstOrDefault(x => Eq(x.ModelId, m.Id)) == null ? null : Store.Indexes.First(x => Eq(x.ModelId, m.Id)).Id, BaselineId = Store.Baselines.FirstOrDefault(x => Eq(x.ModelId, m.Id)) == null ? null : Store.Baselines.First(x => Eq(x.ModelId, m.Id)).Id, CapsuleId = Store.Capsules.FirstOrDefault(x => Eq(x.ModelId, m.Id)) == null ? null : Store.Capsules.First(x => Eq(x.ModelId, m.Id)).Id, BoundedInterpretation = "This dossier binds retained model configuration and computation certificates; it does not claim the world matches surveyed reality.", AccessibilityConditions = new List<string> { "Route conclusions depend on declared topology, direction, capacity, modes, access classes, costs, closures and coordinate reference." }, SpatialEquityEffects = new List<string> { "Review isolated populations, accessibility tails, access restrictions and territorial concentration independently." }, Alternatives = new List<string> { "Preserve at least one feasible alternate corridor and one non-network intervention." }, Unknowns = new List<string> { "Field conditions, temporal schedules, behavior, construction, legal access and data freshness remain unresolved unless evidenced." }, Dissent = new List<string> { "A geographically plausible rendering is not evidence of geographic truth." }, EvidenceNodeIds = m.EvidenceNodeIds.Take(MaxEvidence).ToList() }; Store.Dossiers.Insert(0, d); Save(ctx); AppendLedger(ctx, "DOSSIER_CREATED", d.Id, d.Title, d.ModelFingerprint, HashText(Json.Serialize(d))); OpenCollection(owner, "SPATIAL DECISION DOSSIER", new List<object> { d, d.BoundedInterpretation, d.AuthorityBoundary }.Concat(d.AccessibilityConditions).Concat(d.SpatialEquityEffects).Concat(d.Alternatives).Concat(d.Unknowns).Concat(d.Dissent).Cast<object>().ToList(), "Every interpretation remains model-bound and dissent-preserving."); }
        private static void OpenLedger(Window owner, DeepSystemsContext ctx) { List<SpatialLedgerRecord> rows = ReadLedger(ctx, 32768); OpenCollection(owner, "CARTOGRAPHIC BLACK BOX", new List<object> { VerifyLedger(rows) }.Concat(rows.OrderByDescending(x => x.Sequence).Cast<object>()).ToList(), "Append-only SHA-256 chain; gaps and altered records are surfaced."); }
        private static void ChooseHadalDescent(Window owner, DeepSystemsContext ctx, WorldIndex index) { SpatialWorldModel m = ChooseModel(owner); if (m == null) return; object subject = ChooseObject(owner, "HADAL SPATIAL DESCENT", "Choose a place, territory, connection, infrastructure asset, entity or event.", m.Places.Cast<object>().Concat(m.Territories.Cast<object>()).Concat(m.Connections.Cast<object>()).Concat(m.Infrastructure.Cast<object>()).Concat(m.Entities.Cast<object>()).Concat(m.Events.Cast<object>()).ToList()); if (subject == null) return; string id = SubjectId(subject); List<object> rows = new List<object> { "SUBJECT   ·   " + subject, "WORLD   ·   " + m, "MODEL FINGERPRINT   ·   " + SpatialKernel.Fingerprint(m), "PARENT WORLD   ·   " + (m.ParentModelId ?? "∅"), "SOURCE   ·   " + (m.SourceKind ?? "NATIVE") + ":" + (m.SourceId ?? "∅") }; rows.AddRange(Related(m, id)); rows.AddRange(Evidence(subject).Select(x => "EVIDENCE NODE   ·   " + x).Cast<object>()); OpenCollection(owner, "HADAL SPATIAL DESCENT", rows, "Recursive identity-preserving descent through containment, topology, dependency, movement and evidence."); }
