        {
            string now = Now(); SpatialWorldModel m = new SpatialWorldModel { Id = Id("spatial-world"), Name = name, Description = description, CreatedUtc = now, UpdatedUtc = now, DefaultCrsId = "local-meters" }; m.Parameters["money_to_seconds"] = 60; m.Parameters["energy_to_seconds"] = 1; m.Parameters["risk_to_seconds"] = 900;
