            m.Assumptions.Add("All coordinates and geometries in the starter civilization are synthetic engineering-grid data, not surveyed reality."); m.Assumptions.Add("Free-flow travel times, capacities, access classes, reliability, hazard and demand multipliers are explicit model inputs."); m.Assumptions.Add("Route and stress outputs are decision-support artifacts only and never navigation, emergency dispatch, cadastral or movement authority."); return m;
