        private static void AddPlace(SpatialWorldModel m, string id, string name, string kind, string parent, double x, double y, double capacity, double population) { m.Places.Add(new SpatialPlace { Id = id, Name = name, Kind = kind, ParentId = parent, LayerId = "places", CrsId = m.DefaultCrsId, Position = new SpatialCoordinate(x, y, 0), Capacity = capacity, Population = population }); }
        private static SpatialTerritory Territory(string id, string name, string kind, string parent, string jurisdiction, double minX, double minY, double maxX, double maxY) { SpatialRing ring = new SpatialRing { Id = id + "-shell", Vertices = new List<SpatialCoordinate> { new SpatialCoordinate(minX, minY, 0), new SpatialCoordinate(maxX, minY, 0), new SpatialCoordinate(maxX, maxY, 0), new SpatialCoordinate(minX, maxY, 0) } }; return new SpatialTerritory { Id = id, Name = name, Kind = kind, ParentId = parent, LayerId = "territories", CrsId = "local-meters", Jurisdiction = jurisdiction, Rings = new List<SpatialRing> { ring } }; }
        private static void Link(SpatialWorldModel m, string id, string from, string to, string mode, double length, double seconds, double capacity, bool bidirectional, double cost, double risk) { string infrastructure = Eq(mode, "RAIL") ? "rail-system" : Eq(mode, "ROAD") ? "road-system" : (Eq(mode, "ELEVATOR") || Eq(mode, "CORRIDOR")) ? "tower-life-safety" : Eq(mode, "PORTAL") ? "shelter-system" : null; m.Connections.Add(new SpatialConnection { Id = id, Name = id, FromPlaceId = from, ToPlaceId = to, Mode = mode, LengthMeters = length, FreeFlowSeconds = seconds, CapacityPerHour = capacity, Bidirectional = bidirectional, MonetaryCost = cost, Risk = risk, Reliability = 1 - risk, InfrastructureId = infrastructure }); }
        private static SpatialInfrastructure Infra(string id, string name, string kind, string place, string territory, double capacity, double condition, double criticality, params string[] dependencies) { return new SpatialInfrastructure { Id = id, Name = name, Kind = kind, PlaceId = place, TerritoryId = territory, Capacity = capacity, Utilization = Math.Max(0, capacity) * 0.65, Condition = condition, Redundancy = 1, Criticality = criticality, DependencyIds = dependencies == null ? new List<string>() : dependencies.ToList() }; }
        private static void AddEntity(SpatialWorldModel m, string id, string name, string kind, string from, string to, string mode, double size, double priority) { m.Entities.Add(new SpatialEntity { Id = id, Name = name, Kind = kind, CurrentPlaceId = from, DestinationPlaceId = to, PreferredMode = mode, Size = size, Priority = priority, SpeedMetersPerSecond = Eq(mode, "ROAD") ? 15 : Eq(mode, "RAIL") ? 22 : 1.4 }); }

        private static void Load(DeepSystemsContext ctx) { lock (Gate) { if (Store != null && Eq(LoadedRoot, ctx.StateRoot)) return; LoadedRoot = ctx.StateRoot; Store = null; string path = StorePath(ctx); if (File.Exists(path)) try { Store = Json.Deserialize<SpatialCartographyStore>(File.ReadAllText(path, Encoding.UTF8)); } catch { PreserveCorrupt(path); } if (Store == null && File.Exists(path + ".previous")) try { Store = Json.Deserialize<SpatialCartographyStore>(File.ReadAllText(path + ".previous", Encoding.UTF8)); } catch { } if (Store == null) Store = new SpatialCartographyStore(); NormalizeStore(); } }
        private static void NormalizeStore() { if (Store == null) Store = new SpatialCartographyStore(); Store.Schema = 1; Store.Models = (Store.Models ?? new List<SpatialWorldModel>()).Where(x => x != null).ToList(); Store.Routes = (Store.Routes ?? new List<SpatialRouteArtifact>()).Where(x => x != null).ToList(); Store.Topologies = (Store.Topologies ?? new List<SpatialTopologyArtifact>()).Where(x => x != null).ToList(); Store.Movements = (Store.Movements ?? new List<SpatialMovementArtifact>()).Where(x => x != null).ToList(); Store.StressRuns = (Store.StressRuns ?? new List<SpatialStressArtifact>()).Where(x => x != null).ToList(); Store.Indexes = (Store.Indexes ?? new List<SpatialIndexArtifact>()).Where(x => x != null).ToList(); Store.Capsules = (Store.Capsules ?? new List<SpatialExpeditionCapsule>()).Where(x => x != null).ToList(); Store.Baselines = (Store.Baselines ?? new List<SpatialWorldBaseline>()).Where(x => x != null).ToList(); Store.Dossiers = (Store.Dossiers ?? new List<SpatialDecisionDossier>()).Where(x => x != null).ToList(); foreach (SpatialWorldModel m in Store.Models) NormalizeModel(m); foreach (SpatialStressArtifact x in Store.StressRuns) x.Worlds = (x.Worlds ?? new List<SpatialStressWorldResult>()).Where(v => v != null).ToList(); foreach (SpatialExpeditionCapsule x in Store.Capsules) { x.FrozenParameters = new Dictionary<string, double>(x.FrozenParameters ?? new Dictionary<string, double>(), StringComparer.OrdinalIgnoreCase); x.Assumptions = x.Assumptions ?? new List<string>(); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } foreach (SpatialDecisionDossier x in Store.Dossiers) { x.AccessibilityConditions = x.AccessibilityConditions ?? new List<string>(); x.SpatialEquityEffects = x.SpatialEquityEffects ?? new List<string>(); x.Alternatives = x.Alternatives ?? new List<string>(); x.Unknowns = x.Unknowns ?? new List<string>(); x.Dissent = x.Dissent ?? new List<string>(); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } }
        private static void NormalizeModel(SpatialWorldModel m) { m.Parameters = new Dictionary<string, double>(m.Parameters ?? new Dictionary<string, double>(), StringComparer.OrdinalIgnoreCase); m.CoordinateSystems = (m.CoordinateSystems ?? new List<SpatialCoordinateReference>()).Where(x => x != null).Take(SpatialKernel.MaxCoordinateSystems).ToList(); m.Layers = (m.Layers ?? new List<SpatialLayer>()).Where(x => x != null).Take(SpatialKernel.MaxLayers).ToList(); m.Places = (m.Places ?? new List<SpatialPlace>()).Where(x => x != null).Take(SpatialKernel.MaxPlaces).ToList(); m.Territories = (m.Territories ?? new List<SpatialTerritory>()).Where(x => x != null).Take(SpatialKernel.MaxTerritories).ToList(); m.Connections = (m.Connections ?? new List<SpatialConnection>()).Where(x => x != null).Take(SpatialKernel.MaxConnections).ToList(); m.Infrastructure = (m.Infrastructure ?? new List<SpatialInfrastructure>()).Where(x => x != null).Take(SpatialKernel.MaxInfrastructure).ToList(); m.Entities = (m.Entities ?? new List<SpatialEntity>()).Where(x => x != null).Take(SpatialKernel.MaxEntities).ToList(); m.Events = (m.Events ?? new List<SpatialEvent>()).Where(x => x != null).Take(SpatialKernel.MaxEvents).ToList(); m.Scenarios = (m.Scenarios ?? new List<SpatialScenario>()).Where(x => x != null).Take(SpatialKernel.MaxScenarios).ToList(); m.Assumptions = m.Assumptions ?? new List<string>(); m.EvidenceNodeIds = (m.EvidenceNodeIds ?? new List<string>()).Take(MaxEvidence).ToList(); foreach (SpatialLayer x in m.Layers) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (SpatialPlace x in m.Places) { x.Position = x.Position ?? new SpatialCoordinate(); x.Tags = new Dictionary<string, string>(x.Tags ?? new Dictionary<string, string>(), StringComparer.OrdinalIgnoreCase); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } foreach (SpatialTerritory x in m.Territories) { x.Rings = (x.Rings ?? new List<SpatialRing>()).Where(r => r != null).ToList(); x.Tags = new Dictionary<string, string>(x.Tags ?? new Dictionary<string, string>(), StringComparer.OrdinalIgnoreCase); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (SpatialRing r in x.Rings) r.Vertices = (r.Vertices ?? new List<SpatialCoordinate>()).Where(v => v != null).ToList(); } foreach (SpatialConnection x in m.Connections) { x.Geometry = (x.Geometry ?? new List<SpatialCoordinate>()).Where(v => v != null).ToList(); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } foreach (SpatialInfrastructure x in m.Infrastructure) { x.Commodities = new Dictionary<string, double>(x.Commodities ?? new Dictionary<string, double>(), StringComparer.OrdinalIgnoreCase); x.DependencyIds = x.DependencyIds ?? new List<string>(); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } foreach (SpatialEntity x in m.Entities) { x.ItineraryPlaceIds = x.ItineraryPlaceIds ?? new List<string>(); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } foreach (SpatialEvent x in m.Events) { x.AffectedModeIds = x.AffectedModeIds ?? new List<string>(); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } foreach (SpatialScenario x in m.Scenarios) x.Assumptions = x.Assumptions ?? new List<string>(); }
        private static void TrimStore() { NormalizeStore(); Store.Models = Store.Models.Take(MaxModels).ToList(); Store.Routes = Store.Routes.Take(MaxArtifacts).ToList(); Store.Topologies = Store.Topologies.Take(MaxArtifacts).ToList(); Store.Movements = Store.Movements.Take(MaxArtifacts).ToList(); Store.StressRuns = Store.StressRuns.Take(MaxArtifacts).ToList(); Store.Indexes = Store.Indexes.Take(MaxArtifacts).ToList(); Store.Capsules = Store.Capsules.Take(MaxArtifacts).ToList(); Store.Baselines = Store.Baselines.Take(MaxArtifacts).ToList(); Store.Dossiers = Store.Dossiers.Take(MaxArtifacts).ToList(); }
        private static void Save(DeepSystemsContext ctx) { lock (Gate) { TrimStore(); Store.Revision = Math.Max(0, Store.Revision) + 1; Store.UpdatedUtc = Now(); Store.LastCommitId = Id("spatial-commit"); string path = StorePath(ctx); Directory.CreateDirectory(Path.GetDirectoryName(path)); AtomicWrite(path, Json.Serialize(Store)); } }
        private static void AtomicWrite(string path, string text) { string temp = path + ".tmp." + Guid.NewGuid().ToString("N"); File.WriteAllText(temp, text ?? "", new UTF8Encoding(false)); if (File.Exists(path)) { string previous = path + ".previous"; try { File.Replace(temp, path, previous, true); return; } catch { try { File.Copy(path, previous, true); } catch { } } } if (File.Exists(path)) File.Delete(path); File.Move(temp, path); }
        private static void PreserveCorrupt(string path) { try { if (!File.Exists(path)) return; byte[] bytes = File.ReadAllBytes(path); string destination = path + ".corrupt." + HashBytes(bytes).Substring(0, 16) + ".json"; if (!File.Exists(destination)) File.Copy(path, destination); } catch { } }
        private static string StorePath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-spatial-world-cartography.json"); } private static string LedgerPath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-spatial-world-cartography-ledger.jsonl"); }
        private static void AppendLedger(DeepSystemsContext ctx, string evt, string subject, string detail, string fingerprint, string certificate) { lock (Gate) try { Directory.CreateDirectory(ctx.StateRoot); List<SpatialLedgerRecord> prior = ReadLedger(ctx, 32768); SpatialLedgerRecord last = prior.OrderByDescending(x => x.Sequence).FirstOrDefault(); SpatialLedgerRecord r = new SpatialLedgerRecord { Schema = 1, Sequence = last == null ? 1 : last.Sequence + 1, Utc = Now(), Event = Short(evt, 120), Subject = Short(subject, 512), Detail = Short(detail, MaxLongText), CorrelationId = Store == null ? "" : Store.LastCommitId, ModelFingerprint = Short(fingerprint, 128), CertificateHash = Short(certificate, 128), PrevHash = last == null ? new string('0', 64) : last.EntryHash }; r.EntryHash = LedgerHash(r); byte[] bytes = Encoding.UTF8.GetBytes(Json.Serialize(r) + Environment.NewLine); using (FileStream stream = new FileStream(LedgerPath(ctx), FileMode.Append, FileAccess.Write, FileShare.Read, 4096, FileOptions.WriteThrough)) { stream.Write(bytes, 0, bytes.Length); stream.Flush(); } } catch { } }
        private static List<SpatialLedgerRecord> ReadLedger(DeepSystemsContext ctx, int cap) { List<SpatialLedgerRecord> rows = new List<SpatialLedgerRecord>(); if (!File.Exists(LedgerPath(ctx))) return rows; try { foreach (string line in TakeLast(File.ReadLines(LedgerPath(ctx)).Where(x => !String.IsNullOrWhiteSpace(x)), cap)) try { SpatialLedgerRecord row = Json.Deserialize<SpatialLedgerRecord>(line); if (row != null) rows.Add(row); } catch { } } catch { } return rows; }
        private static string VerifyLedger(List<SpatialLedgerRecord> rows) { if (rows == null || rows.Count == 0) return "EMPTY LEDGER"; rows = rows.OrderBy(x => x.Sequence).ToList(); long expected = rows[0].Sequence; string prior = expected == 1 ? new string('0', 64) : rows[0].PrevHash; foreach (SpatialLedgerRecord row in rows) { if (row.Sequence != expected) return "CHAIN GAP @ " + expected; if (!Eq(row.PrevHash, prior)) return "PREV HASH MISMATCH @ " + row.Sequence; if (!Eq(row.EntryHash, LedgerHash(row))) return "ENTRY HASH MISMATCH @ " + row.Sequence; expected++; prior = row.EntryHash; } return "CHAIN VERIFIED · " + rows.Count.ToString(CultureInfo.InvariantCulture) + " RECORDS"; }
        private static string LedgerHash(SpatialLedgerRecord r) { return HashText(r.Schema + "|" + r.Sequence + "|" + (r.Utc ?? "") + "|" + (r.Event ?? "") + "|" + (r.Subject ?? "") + "|" + (r.Detail ?? "") + "|" + (r.CorrelationId ?? "") + "|" + (r.ModelFingerprint ?? "") + "|" + (r.CertificateHash ?? "") + "|" + (r.PrevHash ?? "")); }

        private static SpatialWorldModel ChooseModel(Window owner) { return ChooseObject(owner, "SELECT SPATIAL WORLD", "Choose an authoritative retained model.", Store.Models.Cast<object>().ToList()) as SpatialWorldModel; }
        private static SpatialScenario ChooseOptionalScenario(Window owner, SpatialWorldModel model) { if (model.Scenarios.Count == 0) return null; List<object> values = new List<object> { "BASE / NO SCENARIO MODIFIER" }; values.AddRange(model.Scenarios.Cast<object>()); object selected = ChooseObject(owner, "SCENARIO WORLD", "Choose a scenario or the base world.", values); return selected as SpatialScenario; }
        private static List<object> Related(SpatialWorldModel m, string id) { List<object> rows = new List<object>(); rows.AddRange(m.Places.Where(x => Eq(x.ParentId, id)).Cast<object>()); rows.AddRange(m.Territories.Where(x => Eq(x.ParentId, id)).Cast<object>()); rows.AddRange(m.Connections.Where(x => Eq(x.FromPlaceId, id) || Eq(x.ToPlaceId, id) || Eq(x.InfrastructureId, id)).Cast<object>()); rows.AddRange(m.Infrastructure.Where(x => Eq(x.PlaceId, id) || Eq(x.TerritoryId, id) || (x.DependencyIds ?? new List<string>()).Contains(id, StringComparer.OrdinalIgnoreCase)).Cast<object>()); rows.AddRange(m.Entities.Where(x => Eq(x.CurrentPlaceId, id) || Eq(x.DestinationPlaceId, id)).Cast<object>()); rows.AddRange(m.Events.Where(x => Eq(x.PlaceId, id) || Eq(x.TerritoryId, id)).Cast<object>()); return rows; }
        private static string SubjectId(object subject) { SpatialPlace p = subject as SpatialPlace; if (p != null) return p.Id; SpatialTerritory t = subject as SpatialTerritory; if (t != null) return t.Id; SpatialConnection c = subject as SpatialConnection; if (c != null) return c.Id; SpatialInfrastructure i = subject as SpatialInfrastructure; if (i != null) return i.Id; SpatialEntity e = subject as SpatialEntity; if (e != null) return e.Id; SpatialEvent v = subject as SpatialEvent; return v == null ? "" : v.Id; }
        private static List<string> Evidence(object subject) { SpatialPlace p = subject as SpatialPlace; if (p != null) return p.EvidenceNodeIds; SpatialTerritory t = subject as SpatialTerritory; if (t != null) return t.EvidenceNodeIds; SpatialConnection c = subject as SpatialConnection; if (c != null) return c.EvidenceNodeIds; SpatialInfrastructure i = subject as SpatialInfrastructure; if (i != null) return i.EvidenceNodeIds; SpatialEntity e = subject as SpatialEntity; if (e != null) return e.EvidenceNodeIds; SpatialEvent v = subject as SpatialEvent; return v == null ? new List<string>() : v.EvidenceNodeIds; }
        private static string Summary() { return Store.Models.Count + " worlds   ·   " + Store.Routes.Count + " route artifacts   ·   " + Store.Topologies.Count + " topology certificates   ·   " + Store.Movements.Count + " movement runs   ·   " + Store.StressRuns.Count + " stress atlases   ·   " + Store.Indexes.Count + " indexes   ·   " + Store.Capsules.Count + " preregistrations   ·   " + Store.Baselines.Count + " baselines   ·   " + Store.Dossiers.Count + " dossiers"; }
        private static void Touch(SpatialWorldModel m) { m.Revision = Math.Max(1, m.Revision) + 1; m.UpdatedUtc = Now(); }
        private static bool Eq(string a, string b) { return String.Equals(a ?? "", b ?? "", StringComparison.OrdinalIgnoreCase); } private static double Number(string raw, double fallback) { double v; return Double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out v) && !Double.IsNaN(v) && !Double.IsInfinity(v) ? v : fallback; } private static int Integer(string raw, int fallback, int min, int max) { int v; if (!Int32.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out v)) v = fallback; return Math.Max(min, Math.Min(max, v)); } private static bool Bool(string raw, bool fallback) { bool v; return Boolean.TryParse(raw, out v) ? v : fallback; }
        private static string[] Fields(string raw) { return (raw ?? "").Split('|'); } private static List<string> Tokens(string raw) { return (raw ?? "").Split(new[] { ',', ';', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries).Select(x => x.Trim()).Where(x => x.Length > 0).Distinct(StringComparer.OrdinalIgnoreCase).ToList(); } private static string Key(string value) { StringBuilder s = new StringBuilder(); foreach (char c in (value ?? "").ToLowerInvariant()) if (Char.IsLetterOrDigit(c) || c == '_' || c == '-') s.Append(c); else if (s.Length > 0 && s[s.Length - 1] != '-') s.Append('-'); return s.ToString().Trim('-'); }
        private static string Short(string value, int cap) { value = value ?? ""; cap = Math.Max(1, cap); return value.Length <= cap ? value : value.Substring(0, cap - 1) + "…"; } private static string HashText(string value) { return HashBytes(Encoding.UTF8.GetBytes(value ?? "")); } private static string HashBytes(byte[] value) { using (SHA256 hash = SHA256.Create()) return BitConverter.ToString(hash.ComputeHash(value ?? new byte[0])).Replace("-", "").ToLowerInvariant(); } private static string Id(string prefix) { return prefix + "-" + DateTime.UtcNow.ToString("yyyyMMddHHmmssfff", CultureInfo.InvariantCulture) + "-" + Guid.NewGuid().ToString("N").Substring(0, 8); } private static string Now() { return DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture); }
        private static IEnumerable<TValue> TakeLast<TValue>(IEnumerable<TValue> source, int count) { Queue<TValue> q = new Queue<TValue>(); foreach (TValue item in source ?? Enumerable.Empty<TValue>()) { q.Enqueue(item); if (q.Count > count) q.Dequeue(); } foreach (TValue item in q) yield return item; }
        private static Window W(Window owner, string title, double width, double height) { return new Window { Title = title, Width = width, Height = height, MinWidth = Math.Min(width, 820), MinHeight = Math.Min(height, 560), Background = Bg, Foreground = Text, WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = owner, FontFamily = new FontFamily("Segoe UI") }; }
        private static DockPanel Shell(string title, string subtitle) { DockPanel root = new DockPanel { Margin = new Thickness(16) }; StackPanel head = new StackPanel { Margin = new Thickness(0, 0, 0, 10) }; head.Children.Add(T(title, 24, Text, FontWeights.Bold)); head.Children.Add(T(subtitle, 12, Muted, FontWeights.Normal)); DockPanel.SetDock(head, Dock.Top); root.Children.Add(head); return root; }
        private static TextBlock T(string value, double size, Brush foreground, FontWeight weight) { return new TextBlock { Text = value ?? "", FontSize = size, Foreground = foreground, FontWeight = weight, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 2) }; }
        private static Button Btn(string label, RoutedEventHandler click) { Button button = new Button { Content = label, Margin = new Thickness(0, 0, 8, 8), Padding = new Thickness(12, 7, 12, 7), Background = Raised, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), MinWidth = 112 }; if (click != null) button.Click += click; return button; }
        private static ListBox List() { return new ListBox { Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), Margin = new Thickness(0, 6, 6, 0), Padding = new Thickness(5), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; }
        private static void Portal(Panel parent, string badge, string title, string description, Action open) { Button button = new Button { Width = 370, Height = 124, Margin = new Thickness(0, 0, 10, 10), Padding = new Thickness(12), Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), HorizontalContentAlignment = HorizontalAlignment.Stretch }; StackPanel content = new StackPanel(); content.Children.Add(T(badge + "   " + title, 14, Accent, FontWeights.Bold)); content.Children.Add(T(description, 11.5, Muted, FontWeights.Normal)); button.Content = content; button.Click += delegate { if (open != null) open(); }; parent.Children.Add(button); }
        private static Brush B(string hex) { return new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex)); }
        private static string Prompt(Window owner, string title, string label, string initial) { Window w = W(owner, "YOMI · " + title, 680, 290); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxShortText, Margin = new Thickness(0, 8, 0, 10), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(8) }; DockPanel.SetDock(editor, Dock.Top); root.Children.Add(editor); WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right }; string result = null; buttons.Children.Add(Btn("OK", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); root.Children.Add(buttons); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static string PromptLarge(Window owner, string title, string label, string initial) { Window w = W(owner, "YOMI · " + title, 800, 560); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxLongText, AcceptsReturn = true, AcceptsTab = true, TextWrapping = TextWrapping.Wrap, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Margin = new Thickness(0, 8, 0, 0), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(10), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; string result = null; buttons.Children.Add(Btn("SAVE", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(editor); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static object ChooseObject(Window owner, string title, string label, IList<object> choices) { Window w = W(owner, "YOMI · " + title, 760, 540); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); ListBox list = List(); list.ItemsSource = choices ?? new List<object>(); if (list.Items.Count > 0) list.SelectedIndex = 0; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; object result = null; buttons.Children.Add(Btn("SELECT", delegate { result = list.SelectedItem; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); list.MouseDoubleClick += delegate { result = list.SelectedItem; if (result != null) w.DialogResult = true; }; DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(list); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static void OpenCollection(Window owner, string title, IList<object> rows, string subtitle) { Window w = W(owner, "YOMI · " + title, 1260, 830); DockPanel root = Shell(title, subtitle); ListBox list = List(); list.ItemsSource = rows ?? new List<object>(); root.Children.Add(list); w.Content = root; w.Show(); }
    }
